function play(){intro.classList.remove('out','play');void intro.offsetWidth;intro.classList.add('play')}
var entered=false;
function enter(){
  if(entered)return;entered=true;
  intro.classList.add('out');
  document.getElementById('go').disabled=true;
  setTimeout(function(){intro.style.display='none'},1400); // remove it so nothing invisible can catch taps
  if (window.BESTA && typeof window.BESTA.enterFromIntro === 'function') window.BESTA.enterFromIntro();
}
document.getElementById('go').onclick=enter;
// Anyone can skip the animation: tap/click anywhere, or press Enter, Space or Escape.
